+    throw new Error('Due from must not be after Due through');
+  }
+  return range;
+}
+
+export function matchesDueRange(date, { from, through }) {
+  if (!from && !through) return true;
+  return Boolean(date) && (!from || date >= from) && (!through || date <= through);
